import type { Metadata } from "next";
import { getTranslations } from "next-intl/server";

import {
  Card,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";

import { listDocuments } from "@/actions/documents";
import { DocumentList } from "@/components/artifacts/document-list";
import {
  PageHeader,
  PageHeaderContent,
  PageHeaderDescription,
  PageHeaderTitle,
} from "@/components/ui/page-header";

export async function generateMetadata(): Promise<Metadata> {
  const t = await getTranslations("artifacts");
  return { title: t("page.title") };
}

/**
 * Every artifact the user created in the active workspace, fetched once;
 * filtering and the preview dialog are client-side.
 *
 * `force-dynamic` because `listDocuments()` reads the session, so a
 * static prerender would fail at build time.
 */
export const dynamic = "force-dynamic";

export default async function ArtifactsPage() {
  const [t, result] = await Promise.all([
    getTranslations("artifacts"),
    listDocuments(),
  ]);

  return (
    <div className="container mx-auto space-y-8 px-4 py-8">
      <PageHeader>
        <PageHeaderContent>
          <PageHeaderTitle>{t("page.heading")}</PageHeaderTitle>
          <PageHeaderDescription>{t("page.description")}</PageHeaderDescription>
        </PageHeaderContent>
      </PageHeader>

      {result.success ? (
        <DocumentList documents={result.data} />
      ) : (
        <Card>
          <CardHeader>
            <CardTitle>{t("page.unavailableTitle")}</CardTitle>
            <CardDescription>{result.error}</CardDescription>
          </CardHeader>
        </Card>
      )}
    </div>
  );
}

import { Card } from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";

export default function ArtifactsLoading() {
  return (
    <div className="container mx-auto space-y-8 px-4 py-8">
      <div className="space-y-2">
        <Skeleton className="h-7 w-32" />
        <Skeleton className="h-4 w-80" />
      </div>

      <div className="flex flex-wrap gap-2">
        {Array.from({ length: 3 }).map((_, index) => (
          <Skeleton key={index} className="h-8 w-20 rounded-full" />
        ))}
      </div>

      <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
        {Array.from({ length: 6 }).map((_, index) => (
          <Card key={index} className="p-5">
            <div className="mb-3 flex items-start gap-3">
              <Skeleton className="size-4 rounded" />
              <div className="min-w-0 flex-1 space-y-2">
                <Skeleton className="h-5 w-48" />
                <Skeleton className="h-4 w-16 rounded-full" />
              </div>
            </div>
            <div className="flex items-center justify-between">
              <Skeleton className="h-4 w-28" />
              <Skeleton className="h-7 w-16 rounded" />
            </div>
          </Card>
        ))}
      </div>
    </div>
  );
}

"use client";

/** Error boundary for the artifacts route. */

import { useEffect } from "react";
import { useTranslations } from "next-intl";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Link } from "@/i18n/navigation";

export default function ArtifactsError({
  error,
  reset,
}: {
  error: Error & { digest?: string };
  reset: () => void;
}) {
  const t = useTranslations("artifacts");

  useEffect(() => {
    console.error("[artifacts] error boundary caught:", error);
  }, [error]);

  return (
    <div className="flex min-h-96 items-center justify-center p-4">
      <div className="w-full max-w-md space-y-4">
        <Alert variant="destructive">
          <AlertDescription>{t("error.description")}</AlertDescription>
        </Alert>

        <div className="flex justify-center gap-3">
          <Button onClick={reset}>{t("error.retry")}</Button>
          <Button
            variant="outline"
            render={<Link href="/" />}
            nativeButton={false}
          >
            {t("error.goHome")}
          </Button>
        </div>
      </div>
    </div>
  );
}

"use server";

/**
 * Artifact library actions over `@intelligo-dev/core/documents`: resolve
 * the caller with `requireWorkspace()`, call the service, map a
 * `DocumentServiceError` to a translated message.
 *
 * Deleting uses `deleteDocumentVersions(actor, id, timestamp)`, which
 * removes every version created strictly after `timestamp`, within the
 * last 30 days. It is a revert, not a hard delete: `deleteLatestVersion`
 * passes one millisecond before the version this page shows, so an
 * artifact with older versions reverts to the previous one, and one
 * with a single version disappears.
 */

import { getTranslations } from "next-intl/server";

import { requireWorkspace } from "@intelligo-dev/auth";
import {
  deleteDocumentVersions,
  getUserDocuments,
  isDocumentServiceError,
  isProductDocument,
  type DocumentListItem,
} from "@intelligo-dev/core/documents";

export type ActionResult<T> =
  { success: true; data: T } | { success: false; error: string };

/**
 * A document list item plus whether its title matches a pattern
 * registered through `@/lib/document-patterns.ts` — drives the
 * "Reports" filter tab.
 */
export type ArtifactListItem = DocumentListItem & { isReport: boolean };

type Translator = Awaited<ReturnType<typeof getTranslations>>;

function friendlyMessageKey(code: string): string | undefined {
  switch (code) {
    case "not_found":
      return "actions.notFound";
    case "forbidden":
      return "actions.forbidden";
    case "invalid_input":
      return "actions.invalidInput";
    case "database_error":
      return "actions.databaseError";
    default:
      return undefined;
  }
}

function friendlyError(t: Translator, error: unknown): string {
  // Unknown errors deliberately map to the generic key — a raw
  // `Error#message` can carry internals (SQL, hostnames) to the UI.
  if (isDocumentServiceError(error)) {
    const key = friendlyMessageKey(error.code);
    return key ? t(key) : t("actions.genericError");
  }
  return t("actions.genericError");
}

/**
 * Every artifact the caller owns in the active workspace, newest first.
 * Filtering happens client-side.
 */
export async function listDocuments(): Promise<
  ActionResult<ArtifactListItem[]>
> {
  try {
    const { workspace, user } = await requireWorkspace();
    const documents = await getUserDocuments({
      workspaceId: workspace.id,
      userId: user.id,
    });

    return {
      success: true,
      data: documents.map((doc) => ({
        ...doc,
        isReport: isProductDocument(doc.title),
      })),
    };
  } catch (error) {
    return {
      success: false,
      error: friendlyError(await getTranslations("artifacts"), error),
    };
  }
}

/**
 * Deletes the version of the artifact this page shows (see the module
 * comment). `latestCreatedAt` is that version's `createdAt` as an ISO
 * string, as `listDocuments` returns it.
 */
export async function deleteLatestVersion(
  id: string,
  latestCreatedAt: string
): Promise<ActionResult<undefined>> {
  const latest = new Date(latestCreatedAt);
  if (Number.isNaN(latest.getTime())) {
    const t = await getTranslations("artifacts");
    return { success: false, error: t("actions.invalidTimestamp") };
  }

  try {
    const { workspace, user } = await requireWorkspace();
    const cutoff = new Date(latest.getTime() - 1).toISOString();

    await deleteDocumentVersions(
      { workspaceId: workspace.id, userId: user.id },
      id,
      cutoff
    );

    return { success: true, data: undefined };
  } catch (error) {
    return {
      success: false,
      error: friendlyError(await getTranslations("artifacts"), error),
    };
  }
}

import "server-only";

/**
 * Title patterns that map a document to an agent label (shown on its
 * card) and to the "Reports" tab. With none registered, every document
 * gets the generic "AI Assistant" label.
 *
 * Call this exactly once, from your composition root: calling it from a
 * request-scoped file (an action, a page) would push duplicate entries
 * onto the same in-memory registry.
 */
export function registerDefaultDocumentPatterns(): void {
  // Registers nothing by default.
}

// Example: label your agent's documents and put them under "Reports"
// (replace the export above):
//
// import { registerDocumentPatterns } from "@intelligo-dev/core/documents";
//
// export function registerDefaultDocumentPatterns(): void {
//   registerDocumentPatterns({
//     productSlug: "default",
//     agentLabel: "Assistant",
//     patterns: ["report", "summary"],
//   });
// }

"use client";

/**
 * The artifact library: a grid of document cards and a reader dialog.
 * Documents render through `@/components/ui/document-viewer`, as in the
 * chat canvas.
 *
 * The "Reports" tab filters on `doc.isReport`, computed server-side from
 * the patterns in `@/lib/document-patterns`; the kind tabs come from the
 * kinds present, so a custom kind gets its own tab. A deleted item is
 * dropped from local state once the server action succeeds.
 */

import { useEffect, useMemo, useState } from "react";
import { useFormatter, useTranslations } from "next-intl";
import { Bot, ExternalLink, File } from "lucide-react";

import { Link } from "@/i18n/navigation";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { ScrollArea } from "@/components/ui/scroll-area";
import {
  DocumentView,
  HtmlPreview,
  documentKindIcon,
  extensionOf,
  isPreviewableTitle,
} from "@/components/ui/document-viewer";
import { AnimatedList, AnimatedListItem } from "@/components/ui/animated-list";

import type { ArtifactListItem } from "@/actions/documents";
import { DocumentActions } from "./document-actions";

/** How much of a document a card shows before it fades out. */
const PREVIEW_LINES = 8;

function head(text: string): string {
  return text.trimStart().split("\n").slice(0, PREVIEW_LINES).join("\n");
}

/**
 * An inline style rather than a class, because the design system keeps
 * gradients out of class names. It fades the bottom: a card shows a
 * document's opening lines.
 */
const PREVIEW_MASK = "linear-gradient(to bottom, black 60%, transparent)";

interface DocumentListProps {
  documents: ArtifactListItem[];
}

/**
 * Relative timestamp that can't cause a hydration mismatch: the server
 * (and the first client render) show a locale-formatted absolute date,
 * and an effect swaps in the relative form once mounted — `Date.now()`
 * during render would differ between server and client.
 */
function RelativeTime({ iso }: { iso: string }) {
  const format = useFormatter();
  const [now, setNow] = useState<Date | null>(null);
  useEffect(() => setNow(new Date()), []);
  const date = new Date(iso);
  return (
    <>
      {now
        ? format.relativeTime(date, now)
        : format.dateTime(date, { dateStyle: "medium" })}
    </>
  );
}

/** The kind's glyph on the tile both the card and the reader use. */
function KindTile({ kind, large }: { kind: string; large?: boolean }) {
  const Icon = documentKindIcon(kind);
  return (
    <span
      aria-hidden="true"
      className={
        large
          ? "grid size-10 shrink-0 place-items-center rounded-lg bg-muted text-muted-foreground"
          : "grid size-8 shrink-0 place-items-center rounded-lg bg-muted text-muted-foreground"
      }
    >
      <Icon className={large ? "size-5" : "size-4"} />
    </span>
  );
}

export function DocumentList({ documents }: DocumentListProps) {
  const t = useTranslations("artifacts");
  const [items, setItems] = useState(documents);
  const [activeFilter, setActiveFilter] = useState<string>("all");
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [view, setView] = useState<"preview" | "source">("preview");

  // `/artifacts?document=<id>` — the chat canvas's "Open in Artifacts" —
  // lands on that document's preview.
  useEffect(() => {
    const id = new URLSearchParams(window.location.search).get("document");
    if (id) setSelectedId(id);
  }, []);

  // Each document opens on its rendered form, not on whatever the last
  // one was left showing.
  useEffect(() => setView("preview"), [selectedId]);

  /**
   * A known kind (text/code/sheet/image) resolves through this item's
   * own messages; a product-defined custom kind falls back to
   * capitalizing the raw value — `t.has` is the check next-intl exposes
   * for "does this key exist" without throwing.
   */
  function kindLabel(kind: string): string {
    const key = `filters.kind.${kind}`;
    return t.has(key) ? t(key) : kind.charAt(0).toUpperCase() + kind.slice(1);
  }

  /** "Code · py" — the same subtitle the chat's artifact card writes. */
  function subtitleOf(doc: ArtifactListItem): string {
    const extension = doc.kind === "code" ? extensionOf(doc.title) : undefined;
    return [kindLabel(doc.kind), extension].filter(Boolean).join(" · ");
  }

  const kinds = useMemo(
    () => Array.from(new Set(items.map((doc) => doc.kind))).sort(),
    [items]
  );
  const hasReports = items.some((doc) => doc.isReport);
  const selected = items.find((doc) => doc.id === selectedId) ?? null;

  const filters: { type: string; label: string; count: number }[] = [
    { type: "all", label: t("filters.all"), count: items.length },
    ...(hasReports
      ? [
          {
            type: "report",
            label: t("filters.reports"),
            count: items.filter((doc) => doc.isReport).length,
          },
        ]
      : []),
    ...kinds.map((kind) => ({
      type: kind,
      label: kindLabel(kind),
      count: items.filter((doc) => doc.kind === kind).length,
    })),
  ];

  const filtered = items.filter((doc) => {
    if (activeFilter === "all") return true;
    if (activeFilter === "report") return doc.isReport;
    return doc.kind === activeFilter;
  });

  function handleDeleted(id: string) {
    setItems((prev) => prev.filter((doc) => doc.id !== id));
    setSelectedId((prev) => (prev === id ? null : prev));
  }

  if (items.length === 0) {
    return <EmptyState />;
  }

  const activeFilterLabel =
    filters.find((filter) => filter.type === activeFilter)?.label ??
    activeFilter;

  // An HTML page or an SVG has a rendered form worth offering; anything
  // else is only ever its source.
  const canPreview = selected ? isPreviewableTitle(selected.title) : false;

  return (
    <>
      {/* One segmented control, not a row of pill buttons: these are
          views of one list, and the counts say what is behind each. */}
      <div
        role="group"
        aria-label={t("filters.all")}
        className="flex w-fit max-w-full flex-wrap items-center gap-0.5 rounded-lg bg-muted p-0.5"
      >
        {filters.map((filter) => {
          const active = activeFilter === filter.type;
          return (
            <button
              key={filter.type}
              type="button"
              aria-pressed={active}
              onClick={() => setActiveFilter(filter.type)}
              className={`h-7 rounded-md px-2.5 text-xs font-medium outline-none transition-colors focus-visible:ring-2 focus-visible:ring-ring ${
                active
                  ? "bg-background text-foreground shadow-xs"
                  : "text-muted-foreground hover:text-foreground"
              }`}
            >
              {filter.label}
              <span className="ml-1.5 tabular-nums opacity-60">
                {filter.count}
              </span>
            </button>
          );
        })}
      </div>

      {filtered.length === 0 ? (
        <FilteredEmptyState filterLabel={activeFilterLabel} />
      ) : (
        <AnimatedList
          as="div"
          className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3"
        >
          {filtered.map((doc) => {
            const previewText = doc.content ? head(doc.content) : "";
            return (
              <AnimatedListItem
                as="div"
                key={doc.id}
                className="group flex cursor-pointer flex-col overflow-hidden rounded-xl border bg-card transition-colors hover:border-foreground/20 focus-within:border-foreground/20"
                onClick={() => setSelectedId(doc.id)}
              >
                {/* The document itself, clipped under a fade. Decorative:
                    the title below is the accessible name. */}
                {doc.kind === "image" && doc.content ? (
                  <div className="h-28 overflow-hidden border-b bg-muted/30">
                    <img
                      src={doc.content}
                      alt=""
                      aria-hidden="true"
                      className="size-full object-cover"
                    />
                  </div>
                ) : previewText ? (
                  <div
                    aria-hidden="true"
                    className="h-28 overflow-hidden border-b bg-muted/30 px-4 pt-3 font-mono text-xs leading-4 whitespace-pre-wrap text-muted-foreground"
                    style={{
                      maskImage: PREVIEW_MASK,
                      WebkitMaskImage: PREVIEW_MASK,
                    }}
                  >
                    {previewText}
                  </div>
                ) : (
                  <div className="grid h-28 place-items-center border-b bg-muted/30">
                    <File
                      aria-hidden="true"
                      className="size-6 text-muted-foreground/40"
                    />
                  </div>
                )}

                <div className="flex min-w-0 items-start gap-3 p-4">
                  <KindTile kind={doc.kind} />
                  <div className="min-w-0 flex-1">
                    {/* A real button, so the card is reachable and
                        named without nesting controls inside it. */}
                    <button
                      type="button"
                      onClick={() => setSelectedId(doc.id)}
                      className="line-clamp-2 text-left text-sm leading-tight font-medium outline-none focus-visible:underline"
                    >
                      {doc.title}
                    </button>
                    <p className="mt-1 truncate text-xs text-muted-foreground">
                      {subtitleOf(doc)}
                    </p>
                    <div className="mt-2 flex min-w-0 items-center gap-1.5 text-xs text-muted-foreground">
                      <Bot className="size-3 shrink-0" />
                      <span className="truncate">{doc.agentLabel}</span>
                      <span className="shrink-0">·</span>
                      <span className="shrink-0">
                        <RelativeTime iso={doc.createdAt} />
                      </span>
                    </div>
                  </div>

                  {doc.isReport ? (
                    <Badge variant="secondary">{t("badge.report")}</Badge>
                  ) : null}

                  <DocumentActions
                    documentId={doc.id}
                    title={doc.title}
                    kind={doc.kind}
                    content={doc.content}
                    createdAt={doc.createdAt}
                    onDeleted={() => handleDeleted(doc.id)}
                    buttonClassName="size-7 opacity-0 transition-opacity group-hover:opacity-100 focus-visible:opacity-100"
                  />
                </div>
              </AnimatedListItem>
            );
          })}
        </AnimatedList>
      )}

      <Dialog
        open={selected !== null}
        onOpenChange={(open) => !open && setSelectedId(null)}
      >
        {selected && (
          /* `sm:` matters: DialogContent's base classes include
             `sm:max-w-sm`, which tailwind-merge does not replace with an
             unprefixed `max-w-*`, so that would win above 640px. */
          <DialogContent className="flex max-h-[80vh] w-full flex-col sm:max-w-5xl">
            <DialogHeader>
              <div className="flex items-start gap-3 pr-8">
                <KindTile kind={selected.kind} large />
                <div className="min-w-0 flex-1">
                  <DialogTitle className="text-left leading-tight">
                    {selected.title}
                  </DialogTitle>
                  <p className="mt-1 truncate text-xs text-muted-foreground">
                    {subtitleOf(selected)} · {selected.agentLabel} ·{" "}
                    <RelativeTime iso={selected.createdAt} />
                  </p>
                </div>
              </div>

              {/* Second row, as in the chat canvas: how to look at the
                  document, then what to do with it. */}
              <div className="flex min-w-0 flex-wrap items-center gap-2 pt-1">
                {canPreview ? (
                  <div
                    role="group"
                    aria-label={t("preview.view")}
                    className="flex items-center rounded-lg bg-muted p-0.5"
                  >
                    {(["preview", "source"] as const).map((option) => (
                      <button
                        key={option}
                        type="button"
                        aria-pressed={view === option}
                        onClick={() => setView(option)}
                        className={`h-6 rounded-md px-2 text-xs font-medium outline-none transition-colors focus-visible:ring-2 focus-visible:ring-ring ${
                          view === option
                            ? "bg-background text-foreground shadow-xs"
                            : "text-muted-foreground hover:text-foreground"
                        }`}
                      >
                        {option === "preview"
                          ? t("preview.rendered")
                          : t("preview.source")}
                      </button>
                    ))}
                  </div>
                ) : null}

                <div className="ml-auto flex items-center gap-1">
                  {selected.conversationId ? (
                    <Button
                      size="sm"
                      variant="outline"
                      render={
                        <Link href={`/chat/${selected.conversationId}`} />
                      }
                      nativeButton={false}
                    >
                      <ExternalLink data-icon="inline-start" />
                      {t("preview.openConversation")}
                    </Button>
                  ) : null}
                  <DocumentActions
                    documentId={selected.id}
                    title={selected.title}
                    kind={selected.kind}
                    content={selected.content}
                    createdAt={selected.createdAt}
                    onDeleted={() => handleDeleted(selected.id)}
                  />
                </div>
              </div>
            </DialogHeader>

            {/* `flex flex-col` is what makes this scroll: ScrollArea's
                viewport is `size-full`, and a percentage height against
                a shrunk flex item resolves to `auto`, so a long document
                would run past the dialog. A flex parent sizes it by
                layout instead. */}
            <ScrollArea className="mt-2 flex min-h-0 flex-1 flex-col">
              {selected.content ? (
                canPreview && view === "preview" ? (
                  <HtmlPreview
                    content={selected.content}
                    title={selected.title}
                  />
                ) : (
                  <DocumentView
                    kind={selected.kind}
                    title={selected.title}
                    content={selected.content}
                  />
                )
              ) : (
                <p className="text-sm italic text-muted-foreground">
                  {t("noContent")}
                </p>
              )}
            </ScrollArea>
          </DialogContent>
        )}
      </Dialog>
    </>
  );
}

function EmptyState() {
  const t = useTranslations("artifacts");
  return (
    <div className="flex flex-col items-center justify-center py-16 text-center">
      <File className="mb-4 size-12 text-muted-foreground/40" />
      <h3 className="mb-1 text-lg font-semibold">{t("emptyState.title")}</h3>
      <p className="max-w-sm text-sm text-muted-foreground">
        {t("emptyState.description")}
      </p>
      {/* An empty artifacts page is a dead end without this: nothing
          on it produces an artifact — the chat surface does. */}
      <Button
        size="sm"
        className="mt-4"
        render={<Link href="/chat" />}
        nativeButton={false}
      >
        {t("emptyState.cta")}
      </Button>
    </div>
  );
}

function FilteredEmptyState({ filterLabel }: { filterLabel: string }) {
  const t = useTranslations("artifacts");
  const lowerFilterLabel = filterLabel.toLowerCase();
  return (
    <div className="flex flex-col items-center justify-center py-16 text-center">
      <File className="mb-4 size-12 text-muted-foreground/40" />
      <h3 className="mb-1 text-lg font-semibold">
        {t("filteredEmptyState.title", { filterLabel: lowerFilterLabel })}
      </h3>
      <p className="text-sm text-muted-foreground">
        {t("filteredEmptyState.description", { filterLabel })}
      </p>
    </div>
  );
}

"use client";

/**
 * Per-artifact actions: copy, download, and delete. Delete reverts to an
 * earlier saved version when one exists rather than removing the
 * artifact, and refuses artifacts older than 30 days; the confirm dialog
 * says so.
 */

import { useState, useTransition } from "react";
import { useTranslations } from "next-intl";
import { Check, Copy, Download, Trash2 } from "lucide-react";
import { toast } from "sonner";

import { useRouter } from "@/i18n/navigation";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  documentKindExtension,
  fileNameOf,
} from "@/components/ui/document-viewer";
import { Spinner } from "@/components/ui/spinner";

import { deleteLatestVersion } from "@/actions/documents";

interface DocumentActionsProps {
  documentId: string;
  title: string;
  kind: string;
  content: string | null;
  createdAt: string;
  /** Called after a successful delete, e.g. to drop the item from local state. */
  onDeleted?: () => void;
  buttonClassName?: string;
}

export function DocumentActions({
  documentId,
  title,
  kind,
  content,
  createdAt,
  onDeleted,
  buttonClassName,
}: DocumentActionsProps) {
  const t = useTranslations("artifacts");
  const router = useRouter();
  const [copied, setCopied] = useState(false);
  const [confirmOpen, setConfirmOpen] = useState(false);
  const [isDeleting, startDeleting] = useTransition();

  /**
   * Saved the way the canvas saves it: an image is already a URL, and
   * everything else becomes a blob typed by its kind, so a sheet lands
   * as a `.csv` a spreadsheet will open rather than as plain text.
   */
  function handleDownload() {
    if (!content) return;
    const link = document.createElement("a");
    if (kind === "image") {
      link.href = content;
    } else {
      link.href = URL.createObjectURL(
        new Blob([content], {
          type: kind === "sheet" ? "text/csv" : "text/plain",
        })
      );
    }
    link.download = fileNameOf(title, documentKindExtension(kind));
    link.click();
    if (link.href.startsWith("blob:")) URL.revokeObjectURL(link.href);
  }

  async function handleCopy() {
    if (!content) return;
    try {
      await navigator.clipboard.writeText(content);
      setCopied(true);
      toast.success(t("documentActions.copySuccess"));
      setTimeout(() => setCopied(false), 2000);
    } catch {
      toast.error(t("documentActions.copyErrorTitle"), {
        description: t("documentActions.copyErrorDescription"),
      });
    }
  }

  function handleDelete() {
    startDeleting(async () => {
      const result = await deleteLatestVersion(documentId, createdAt);
      if (!result.success) {
        toast.error(result.error);
        return;
      }
      toast.success(t("documentActions.deleteSuccess"));
      setConfirmOpen(false);
      onDeleted?.();
      router.refresh();
    });
  }

  return (
    <div className="flex items-center gap-1">
      {content && (
        <Button
          type="button"
          variant="ghost"
          size="icon"
          onClick={(event) => {
            event.stopPropagation();
            void handleCopy();
          }}
          className={buttonClassName}
          title={
            copied
              ? t("documentActions.copyTooltipCopied")
              : t("documentActions.copyTooltipDefault")
          }
        >
          {copied ? (
            <Check className="size-4 text-success" />
          ) : (
            <Copy className="size-4" />
          )}
        </Button>
      )}

      {content && (
        <Button
          type="button"
          variant="ghost"
          size="icon"
          onClick={(event) => {
            event.stopPropagation();
            handleDownload();
          }}
          className={buttonClassName}
          title={t("documentActions.downloadTooltip")}
        >
          <Download className="size-4" />
        </Button>
      )}

      <Button
        type="button"
        variant="ghost"
        size="icon"
        onClick={(event) => {
          event.stopPropagation();
          setConfirmOpen(true);
        }}
        className={buttonClassName}
        title={t("documentActions.deleteTooltip")}
      >
        <Trash2 className="size-4" />
      </Button>

      <Dialog open={confirmOpen} onOpenChange={setConfirmOpen}>
        <DialogContent onClick={(event) => event.stopPropagation()}>
          <DialogHeader>
            <DialogTitle>{t("documentActions.deleteDialogTitle")}</DialogTitle>
            <DialogDescription>
              {t("documentActions.deleteDialogDescription")}
            </DialogDescription>
          </DialogHeader>
          <DialogFooter>
            <Button
              type="button"
              variant="outline"
              onClick={() => setConfirmOpen(false)}
              disabled={isDeleting}
            >
              {t("documentActions.cancel")}
            </Button>
            <Button
              type="button"
              variant="destructive"
              onClick={handleDelete}
              disabled={isDeleting}
            >
              {isDeleting ? <Spinner /> : t("documentActions.delete")}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

